fn is_min_heap(a: &Vec<i32>) -> bool {
    let n = a.len();
    // Only need to check indices of all parent nodes:
    // parents are from index 0 up to floor(n/2) - 1
    // because nodes beyond floor(n/2)-1 have no children
    let last_parent = n / 2;

    for i in 0..last_parent {
        let left = 2 * i + 1;
        let right = 2 * i + 2;

        // Check if left child exists and violates min-heap property
        if left < n && a[left] < a[i] {
            return false;
        }

        // Check if right child exists and violates min-heap property
        if right < n && a[right] < a[i] {
            return false;
        }
    }

    true
}